public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    for (String s : strings) {
        if (s != null) {
            maxLen = Math.max(maxLen, s.length());
        }
    }

    // Check from largest possible length down to 1
    for (int len = maxLen; len >= 1; len--) {
        // Collect all substrings of length len from all strings
        java.util.Set<String> substrings = new java.util.HashSet<>();
        for (String s : strings) {
            if (s == null || s.length() < len) continue;
            for (int i = 0; i <= s.length() - len; i++) {
                substrings.add(s.substring(i, i + len));
            }
        }

        // For each substring, check if it or its reverse appears in any string
        for (String sub : substrings) {
            String reversed = new StringBuilder(sub).reverse().toString();
            boolean found = false;
            for (String s : strings) {
                if (s == null) continue;
                if (s.contains(sub) || s.contains(reversed)) {
                    found = true;
                    break;
                }
            }
            if (found) {
                return len;
            }
        }
    }

    return 0;
}

