public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    if (n <= 0) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Build adjacency list
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i < n * n; i++) {
        adj.add(new ArrayList<>());
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            int idx1 = x1 * n + y1;
            int idx2 = x2 * n + y2;
            adj.get(idx1).add(new int[]{x2, y2});
            adj.get(idx2).add(new int[]{x1, y1});
        }
    }

    // BFS
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{sx, sy});
    visited[sx][sy] = true;

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int cx = curr[0], cy = curr[1];
        if (cx == ex && cy == ey) {
            return "can be travelled";
        }
        int idx = cx * n + cy;
        for (int[] neighbor : adj.get(idx)) {
            int nx = neighbor[0], ny = neighbor[1];
            if (!visited[nx][ny]) {
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

