public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Date string cannot be null or empty");
    }

    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Date must be in format 'MM dd yyyy'");
    }

    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Month must be between 1 and 12");
        }
        if (day < 1 || day > 31) {
            throw new IllegalArgumentException("Day must be between 1 and 31");
        }
        if (year < 1) {
            throw new IllegalArgumentException("Year must be positive");
        }

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();

        String monthName = localDate.getMonth().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String dayOfWeekName = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return String.format("%s %d, %d is a %s", monthName, day, year, dayOfWeekName);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid date format: " + e.getMessage());
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date: " + e.getMessage());
    }
}

