public String getSmallestString(int n, int k) {
    if (n <= 0 || k < n || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input: n must be positive and k must be between n and 26*n");
    }

    char[] result = new char[n];
    int remaining = k;

    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        remaining--;
    }

    // Now we need to distribute 'remaining' extra value across the n characters
    // To get lexicographically smallest, we should put as much as possible on the rightmost characters
    // Each character can take at most 25 extra (from 'a'=1 to 'z'=26)

    for (int i = n - 1; i >= 0; i--) {
        if (remaining <= 0) break;

        int add = Math.min(remaining, 25);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

