public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);

    // Precompute which pairs sum to a perfect square
    boolean[][] isSquare = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int sqrt = (int) Math.sqrt(sum);
                isSquare[i][j] = (sqrt * sqrt == sum);
            }
        }
    }

    int[] count = {0};
    boolean[] used = new boolean[n];

    // Backtracking
    backtrack(0, n, A, isSquare, used, count);

    return count[0];
}

