    int idx = 0;
    // There are rows + cols - 1 diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        // Determine the starting point of the diagonal
        int startRow, startCol;
        if (d < cols) {
            startRow = 0;
            startCol = d;
        } else {
            startRow = d - cols + 1;
            startCol = cols - 1;
        }

        // Traverse the diagonal
        int r = startRow;
        int c = startCol;
        if (d % 2 == 0) {
            // Go up-right: row decreases, col increases
            while (r >= 0 && c < cols) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // Go down-left: row increases, col decreases
            while (r < rows && c >= 0) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }

    return result;
}

