public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if all three points are the same
    if (x1 == x2 && y1 == y2 && x2 == x3 && y2 == y3) {
        return false;
    }

    // Check if any two points are the same
    boolean p1p2 = (x1 == x2 && y1 == y2);
    boolean p1p3 = (x1 == x3 && y1 == y3);
    boolean p2p3 = (x2 == x3 && y2 == y3);

    if (p1p2 || p1p3 || p2p3) {
        return false;
    }

    // Check if the three points are collinear using cross product
    // (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1) == 0 means collinear
    long cross = (long)(x2 - x1) * (y3 - y1) - (long)(y2 - y1) * (x3 - x1);

    return cross != 0;
}

